<?php
namespace Tests\Feature;
use App\Models\{Company,SubscriptionPlan,User}; use App\Services\SubscriptionAccountService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SubscriptionFoundationTest extends TestCase { use RefreshDatabase;
 public function test_catalogue_contains_the_exact_commercial_prices_and_limits(): void { $this->assertDatabaseHas('subscription_plans',['key'=>'basic','monthly_price'=>2500,'annual_price'=>27500,'company_limit'=>1,'user_limit'=>2,'product_limit'=>50]);$this->assertDatabaseHas('subscription_plans',['key'=>'gold','monthly_price'=>20000,'annual_price'=>220000,'company_limit'=>5,'user_limit'=>15,'product_limit'=>1000]); }
 public function test_first_account_gets_one_trial_and_one_credit_only(): void { $user=User::factory()->create();$company=Company::create(['name'=>'Entreprise essai','email'=>'essai@example.test','number1'=>'90000000','created_by'=>$user->id]);$service=app(SubscriptionAccountService::class);$account=$service->ensureFor($company,$user->id);$service->ensureFor($company->fresh(),$user->id);$company=$company->fresh();$this->assertSame(3,(int)$company->sms_count);$this->assertSame(3,(int)$company->whatsapp_count);$this->assertDatabaseCount('subscription_accounts',1);$this->assertDatabaseCount('subscriptions',1);$this->assertSame('trial',$account->subscriptions()->first()->status); }
 public function test_annual_prices_are_eleven_months_and_quotas_are_twelve_months(): void { foreach(['basic'=>[2500,27500,10,120],'bronze'=>[5000,55000,20,240],'silver'=>[10000,110000,50,600],'gold'=>[20000,220000,100,1200]] as $key=>[$monthly,$annual,$quota,$annualQuota]){$p=SubscriptionPlan::where('key',$key)->firstOrFail();$this->assertSame($monthly*11,(int)$p->annual_price);$this->assertSame($quota*12,$annualQuota);} }
}
